function supported(code){const tag=String(code||'').toLowerCase().replace(/_/g,'-');if(/^zh-yue(?:-|$)/.test(tag))return 'yue';if(/^zh-wuu(?:-|$)/.test(tag))return 'wuu';if(/^pa-arab(?:-|$)/.test(tag))return 'pnb';if(/^ar-eg(?:-|$)/.test(tag))return 'arz';const base=tag.split('-')[0],aliases={fil:'tl',cmn:'zh'};const normalized=aliases[base]||base;return Object.hasOwn(I18N,normalized)?normalized:null;}
