function valid(s){return s&&s.version===1&&Array.isArray(s.names)&&s.names.length>=2&&s.names.length<=10&&s.names.every(n=>typeof n==='string'&&n.trim().length>0&&n.length<=24)&&Number.isInteger(s.limit)&&s.limit>0&&s.limit<=9999&&Array.isArray(s.rounds)&&s.rounds.length<=10000&&s.rounds.every(r=>Array.isArray(r)&&r.length===s.names.length&&r.every(v=>Number.isInteger(v)&&v>=0&&v<=9999));}
