function isComplete(game=state){return game.rounds.length>0&&game.names.some((_,i)=>game.rounds.reduce((sum,r)=>sum+r[i],0)>=game.limit);}
function copyGame(game){return {version:1,names:[...game.names],limit:game.limit,rounds:game.rounds.map(r=>[...r]),draft:game.names.map((_,i)=>game.draft?.[i]??0)};}
